data MainRecord = MainRecord
  { mainRecordMain :: Int
  , mainRecordPath :: [String]
  , mainRecordHead :: Maybe String
  } deriving (Show, Eq)

defaultMainRecord :: MainRecord
defaultMainRecord = MainRecord
  { mainRecordMain = 0
  , mainRecordPath = []
  , mainRecordHead = Nothing
  }

decodeMainRecord :: Fields -> Either String MainRecord
decodeMainRecord kv =
  MainRecord
    <$> fieldInt "main" kv
    <*> fieldList "path" kv
    <*> fieldOpt "head" kv

encodeMainRecord :: MainRecord -> Fields
encodeMainRecord r =
  [ ("main", encInt (mainRecordMain r))
  , ("path", encList (mainRecordPath r))
  , ("head", encOpt (mainRecordHead r))
  ]

mainRecordMainL :: Lens' MainRecord (Int)
mainRecordMainL k r = (\v -> r { mainRecordMain = v }) <$> k (mainRecordMain r)
{-# INLINE mainRecordMainL #-}

mainRecordPathL :: Lens' MainRecord ([String])
mainRecordPathL k r = (\v -> r { mainRecordPath = v }) <$> k (mainRecordPath r)
{-# INLINE mainRecordPathL #-}

mainRecordHeadL :: Lens' MainRecord (Maybe String)
mainRecordHeadL k r = (\v -> r { mainRecordHead = v }) <$> k (mainRecordHead r)
{-# INLINE mainRecordHeadL #-}

